window.VA = {"site": {"name": "St. Jerome Cemetery", "title": "St. Jerome Cemetery Veterans Memorial", "address": "125 Saint Jerome Avenue, Holyoke, MA", "kind": "cemetery", "center": [42.2074, -72.6282], "zoom": 17}, "veterans": [{"id": "sj_mooney_james_l_sr", "name": "James L. Mooney Sr.", "era": "Korea", "branch": "U.S. Air Force", "branchLabel": "Air Force \u00b7 Korea", "lat": 42.2078, "lng": -72.629, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/mooney_james_l_sr.jpg", "extraPhotos": [], "narrative": "James L. Mooney Sr. served as a Staff Sergeant in the United States Air Force during the Korean War. His marker at St. Jerome Cemetery remembers him as a beloved husband, father, grandfather, and brother (1933\u20132023). If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch1"}, {"id": "sj_ripa_louis_j", "name": "Louis J. Ripa", "era": "World War II", "branch": "U.S. Navy", "branchLabel": "Navy \u00b7 WWII", "lat": 42.2078, "lng": -72.62855, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/ripa_louis_j.jpg", "extraPhotos": [], "narrative": "Louis J. Ripa served as an Aviation Ordnanceman Second Class in the United States Navy during World War II (1911\u20131992). If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch1"}, {"id": "sj_mckenzie_t", "name": "T. McKenzie", "era": "World War I", "branch": "", "branchLabel": "", "lat": 42.2078, "lng": -72.6281, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/mckenzie_t.jpg", "extraPhotos": [], "narrative": "A veteran of the First World War surnamed McKenzie (first initial T.) rests at St. Jerome Cemetery, his service marked by a World War One veteran's star at the grave. The monument is partly obscured; further details await research. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch1"}, {"id": "sj_scollard", "name": "Scollard", "era": "World War II", "branch": "", "branchLabel": "", "lat": 42.2078, "lng": -72.62765, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/scollard.jpg", "extraPhotos": [], "narrative": "A member of the Scollard family who served in World War II rests beneath this monument at St. Jerome Cemetery, marked by a 1941\u20131945 World War II veteran's emblem. The given name is not shown on the family stone and awaits research. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch1"}, {"id": "sj_harnois_homer_j", "name": "Homer Joseph Harnois", "era": "World War II", "branch": "U.S. Navy", "branchLabel": "Navy \u00b7 WWII", "lat": 42.20815, "lng": -72.629, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/harnois_homer_j.jpg", "extraPhotos": [], "narrative": "Homer Joseph Harnois served as a Seaman First Class in the United States Navy during World War II (1921\u20132004). If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch1"}, {"id": "sj_gorman_louis_o", "name": "Louis O. Gorman", "era": "World War II", "branch": "U.S. Army", "branchLabel": "Army \u00b7 WWII", "lat": 42.20815, "lng": -72.62855, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/gorman_louis_o.jpg", "extraPhotos": [], "narrative": "Louis O. Gorman (1924\u20131991) served as a Private in the United States Army during World War II. Serving as a Private in the U.S. Army, Louis\u2019s experience was defined by the raw, unvarnished mud, heavy packs, and marching orders of the ground infantry during the height of the European or Pacific liberation campaigns. Louis Gorman was part of the greatest generation of working-class Holyoke families. He married Anne Gyursky, and together they built a life centered around neighborhood institutions, raising their children to become prominent community leaders. The Gormans were fixtures of the community of St. Jerome parish. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch1"}, {"id": "sj_clarke_walter_j", "name": "Walter J. Clarke", "era": "World War II", "branch": "U.S. Navy", "branchLabel": "Navy \u00b7 WWII", "lat": 42.20815, "lng": -72.6281, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/clarke_walter_j.jpg", "extraPhotos": [], "narrative": "Walter J. Clarke (1923\u20131990) served as a Quartermaster Second Class in the United States Navy during World War II. As a Quartermaster, Walter fought on the bridge of a ship. His hands on the wheel, navigating vessels, tracking weather, and reading the signals through binoculars across hazardous ocean expanses. Walter was a man deeply woven into the spiritual fabric of Holyoke. Following his wartime service he returned home to plant deep roots in Elmwood on Merrick Avenue. He found his ultimate calling as a member of the Catholic clergy, becoming ordained as a Permanent Deacon in the Roman Catholic Church. The Reverend Mr. Walter J. Clarke spent the rest of his life serving the local Catholic community alongside his wife, Theresa - a dedicated nurse at Providence and Holyoke Hospitals. Walter passed away in 1990 at the age of 67. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch1"}, {"id": "sj_welch_edward_j", "name": "Edward J. Welch", "era": "World War I", "branch": "U.S. Army", "branchLabel": "Army \u00b7 WWI", "lat": 42.20815, "lng": -72.62765, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/welch_edward_j.jpg", "extraPhotos": [], "narrative": "Born in Holyoke in 1894, Edward Welch was among the first wave of young men from the paper mills of Holyoke to be shipped overseas into the absolute hell of the Western Front. Edward\u2019s name is etched into the definitive text, Holyoke in the Great War. He served alongside other local boys from the mills in the 26th Infantry Division, famously known as the \u201cYankee Division,\u201d composed of National Guard units from New England. When they arrived in France, they were thrown into some of the most notorious sectors of the Western Front: Chemin des Dames, La Reine (Toul), and the blood-soaked earth northwest of Ch\u00e2teau-Thierry. For Edward, the war was fought at eye level with rats, rotting sandbags, and the heavy, sweet stench of gangrene and chemical mustard gas. The Yankee Division faced unrelenting German artillery bombardment (\u201cflak\u201d and high explosives) and grueling trench raids where combat was hand-to-hand in the dark. Edward gave his life on January 15, 1918, at the height of World War I, right as the division was adapting to the freezing winter horrors of the frontline. He was brought back home to rest eternally in the Welch family plot at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch1"}, {"id": "sj_mcintyre_patrick_f", "name": "Patrick F. McIntyre", "era": "World War II", "branch": "U.S. Army", "branchLabel": "Army \u00b7 WWII", "lat": 42.2085, "lng": -72.629, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/mcintyre_patrick_f.jpg", "extraPhotos": [], "narrative": "Patrick F. McIntyre was a working-class Irish-American who lived in Holyoke's dense downtown neighborhoods. For decades, he was a parishioner at St. Jerome Church and lived on Elm Street. He served as a Private First Class (PFC) in the U.S. Army during World War II. As an infantryman, his war was defined by the grueling day-to-day survival of the ground forces\u2014carrying heavy field packs, digging foxholes, and enduring the damp European winters or muddy terrain. When Patrick returned to Holyoke, he went straight into the heart of \u201cThe Paper City\u2019s\u201d economy, working for decades as a machinist and laborer in the local paper mills. He married his wife, Mary, and they raised their family within walking distance of the mills. His marker at St. Jerome Cemetery is shared with family under the words \u201cAlways Together.\u201d The phrase \u201cAlways Together\u201d carved onto his monument at St. Jerome Cemetery isn't just a generic sentiment. Patrick and Mary were known in their neighborhood for being practically inseparable for over 40 years. When Mary passed away, Patrick spent his remaining years visiting her grave regularly until he was finally laid to rest right beside her, fulfilling the promise on the stone. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch1"}, {"id": "sj_kaeble_raymond_r", "name": "Raymond R. Kaeble", "era": "World War II", "branch": "U.S. Army Air Forces", "branchLabel": "Army Air Forces \u00b7 WWII", "lat": 42.2085, "lng": -72.62855, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/kaeble_raymond_r.jpg", "extraPhotos": [], "narrative": "Raymond R. Kaeble served as a Staff Sergeant in the United States Army Air Forces during World War II (1923\u20131986). His marker gives the branch in its wartime form, Army Air Corps. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch1"}, {"id": "sj_netkovick_adolph_c", "name": "Adolph C. Netkovick", "era": "World War II", "branch": "U.S. Army", "branchLabel": "Army \u00b7 WWII", "lat": 42.2070361, "lng": -72.6287528, "photo": "/Veteran-Archives/photos/st-jerome/netkovick_adolph_c.jpg", "extraPhotos": [], "narrative": "Adolph C. Netkovick (1913\u20131982) served as a Technical Sergeant in the United States Army during World War II. His early life was rooted in a traditional working-class home in Willamansette. His wartime deployment was exceptionally grueling, serving in the notorious China-Burma-India (CBI) Theater - a logistical and combat nightmare defined by dense jungles, monsoons, and extreme isolation. As a Technical Sergeant, his leadership was vital to keeping supply lines open and troops moving under primitive conditions. Returning to civilian life, Adolph became a prominent local veterans' leader. He passed away in 1982 at the age of 68. He rests at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch2-geo"}, {"id": "sj_rigali_joseph_w", "name": "Joseph W. Rigali", "era": "World War II", "branch": "U.S. Army", "branchLabel": "Army \u00b7 WWII", "lat": 42.2074667, "lng": -72.6279056, "photo": "/Veteran-Archives/photos/st-jerome/rigali_joseph_w.jpg", "extraPhotos": [{"src": "https://raw.githubusercontent.com/markwot-ops/Veteran-Archives/main/photos/st-jerome/rigali_family.jpg", "caption": "The Lucchesi\u2013Rigali family monument"}], "narrative": "Joseph W. Rigali was born in 1911, into one of the foundational Italian-American families of Holyoke\u2019s downtown business district, whose relatives famously ran the historic confectionery, fruit, and real estate blocks along High Street and Main Street. During World War II, Joseph answered the call to arms - leaving the family businesses to serve his country during the height of the global conflict. Returning to the Pioneer Valley after the war, he lived out his life deeply connected to the civic fabric of the community. Joseph passed away in 1983 at the age of 72 and was laid to rest with the Lucchesi\u2013Rigali family at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch2-geo"}, {"id": "sj_eckart_emil_a", "name": "Emil A. Eckart", "era": "World War I", "branch": "", "branchLabel": "", "lat": 42.2073222, "lng": -72.6279056, "photo": "/Veteran-Archives/photos/st-jerome/eckart_emil_a.jpg", "extraPhotos": [], "narrative": "Emil A. Eckart (1896\u20131948) was raised in the working-class families of Holyoke. His life was tied to the community where he lived at 75 Sycamore Street with his family. During World War I, Emil left the valley to answer the call of his nation. The branch of his service is not shown on the family stone and awaits further research. After the armistice, Emil planted deep roots. He shared his life with his wife, Agnes (Dazelle) Eckart, a dedicated registered nurse who graduated from the Holyoke School of Nursing in 1918 and served patients at Holyoke Hospital for decades. Emil passed away in 1948 at the age of 52, leaving a legacy of service to his community and country. He rests eternally at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch2-geo"}, {"id": "sj_obrien_frank_j", "name": "Frank J. O'Brien", "era": "World War II", "branch": "U.S. Army", "branchLabel": "Army \u00b7 WWII", "lat": 42.2072222, "lng": -72.6278389, "photo": "/Veteran-Archives/photos/st-jerome/obrien_frank_j.jpg", "extraPhotos": [{"src": "https://raw.githubusercontent.com/markwot-ops/Veteran-Archives/main/photos/st-jerome/obrien_family.jpg", "caption": "The O'Brien family monument"}], "narrative": "Frank J. O'Brien (1918\u20131981) served as a Private First Class (PFC) in the United States Army during World War II. Frank was part of the generation of young men who swapped their civilian clothes for a uniform, enduring the heavy packs, forced marches, and foxhole realities of the ground forces. He survived the chaos of the war and returned to the Paper City to plant his roots. Frank spent his post-war years living and working within the local community until his passing in 1981 at the age of 62. He rests at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch2-geo"}, {"id": "sj_griffin_thomas_j", "name": "Thomas J. Griffin", "era": "Spanish-American War", "branch": "U.S. Army", "branchLabel": "Army \u00b7 Spanish-American War", "lat": 42.2087167, "lng": -72.6287611, "photo": "/Veteran-Archives/photos/st-jerome/griffin_thomas_j.jpg", "extraPhotos": [], "narrative": "Thomas J. Griffin served with Company L, 34th United States Volunteer Infantry, a federal volunteer regiment raised specifically for service in the Philippines during the Spanish-American War era. For Thomas, the war meant leaving the brick mills of Holyoke for grueling tropical campaigns overseas, enduring the constant threat of disease, harsh jungle terrain, and guerrilla warfare. He survived the conflict and returned to the Pioneer Valley to live out his days among his peers. He rests with the Griffin family at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch2-geo"}, {"id": "sj_kelley_william_t", "name": "William T. Kelley", "era": "World War II", "branch": "U.S. Army", "branchLabel": "Army \u00b7 WWII", "lat": 42.2071389, "lng": -72.6278389, "photo": "/Veteran-Archives/photos/st-jerome/kelley_william_t.jpg", "extraPhotos": [], "narrative": "William T. Kelley (1917\u20132005) served as a Sergeant in the United States Army during World War II. His wartime experience was defined by the raw, unvarnished dangers of the ground infantry. His exceptional valor and sacrifices on the battlefield are documented by his decorations; he was awarded the Bronze Star Medal for heroic or meritorious achievement and the Purple Heart for wounds sustained in action under enemy fire. Returning home to Holyoke, William transitioned back to the civilian rhythm of the valley, living a long life before passing away in 2005 at the age of 88. He rests at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": ["Bronze Star", "Purple Heart"], "status": "located", "source": "st-jerome-field-batch2-geo"}, {"id": "sj_orourke_richard_w", "name": "Richard W. O'Rourke", "era": "World War I", "branch": "U.S. Army", "branchLabel": "Army \u00b7 WWI", "lat": 42.206025, "lng": -72.6282639, "photo": "/Veteran-Archives/photos/st-jerome/orourke_richard_w.jpg", "extraPhotos": [], "narrative": "Richard W. O'Rourke (1896\u20131972) served as a Corporal in the United States Army during World War I. His name and wartime service are officially etched into the definitive local text, Holyoke in the Great War. Richard's experience was shaped by the brutal, muddy logistics of the Western Front, where he served alongside other local boys from Holyoke's neighborhoods and mills. Surviving the harsh winter conditions, heavy artillery bombardments, and frontline realities of the European theater, Richard returned home to the Pioneer Valley in 1919. He spent the remainder of his life as a fixture of Holyoke's community before passing away in 1972 at the age of 76. He rests eternally at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch2-geo"}, {"id": "sj_obrien_edward_f", "name": "Edward F. O'Brien", "era": "", "branch": "", "branchLabel": "", "lat": 42.2071889, "lng": -72.6278833, "photo": "/Veteran-Archives/photos/st-jerome/obrien_edward_f.jpg", "extraPhotos": [], "narrative": "Edward F. O'Brien (died December 2, 1951) rests here with his wife, Anna Joyce (died January 14, 1998). His marker carries no military insignia, so his veteran status is unconfirmed; he lies beside World War II veteran Frank J. O'Brien (1918\u20131981). If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch2-geo"}, {"id": "sj_beaudry_wilfred_r", "name": "Wilfred R. Beaudry", "era": "World War II", "branch": "U.S. Navy", "branchLabel": "Navy \u00b7 WWII", "lat": 42.2066, "lng": -72.6296, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/beaudry_wilfred_r.jpg", "extraPhotos": [], "narrative": "Wilfred R. Beaudry was born into the vibrant French-Canadian enclaves that formed a massive part of Holyoke\u2019s working-class mill workforce. Answering the call during World War II, Wilfred served as an enlisted sailor in the United States Navy. His daily reality was shaped by life at sea\u2014the constant roll of the ship, standing long watches, and enduring the intense humidity or freezing salt spray of global deployments. After victory was secured, Wilfred returned home to the Pioneer Valley, trading his uniform for civilian life and contributing his labor to the local community. He rests eternally among his family at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch3"}, {"id": "sj_whalen_joseph_l", "name": "Joseph L. Whalen", "era": "World War II", "branch": "U.S. Coast Guard", "branchLabel": "Coast Guard \u00b7 WWII", "lat": 42.2066, "lng": -72.6291, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/whalen_joseph_l.jpg", "extraPhotos": [], "narrative": "Joseph L. Whalen (June 1, 1926 \u2013 November 15, 2000) served as a Seaman First Class in the United States Coast Guard during World War II \u2014 the service that guarded convoys, manned landing craft, and patrolled home waters. His monument at St. Jerome Cemetery also bears the emblem of the Holyoke Fire Department, marking a life of service continued at home as a Holyoke firefighter. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch3"}, {"id": "sj_brodeur_raymond_roy", "name": "Raymond Roy Brodeur", "era": "World War II", "branch": "U.S. Navy", "branchLabel": "Navy \u00b7 WWII", "lat": 42.2066, "lng": -72.6286, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/brodeur_raymond_roy.jpg", "extraPhotos": [], "narrative": "Raymond Roy Brodeur (1925\u20132007) was part of the broad mobilization of working-class families from the Pioneer Valley who answered the call to arms during World War II. Born on June 4, 1925, Raymond entered naval service as an Aviation Machinist\u2019s Mate Third Class (AMM3). His rate put him on the high-octane line of wartime naval aviation, where his daily reality was stained with oil, grease, and hydraulic fluid as he repaired, tuned, and tested complex aircraft engines to ensure naval pilots could take off and make it back to their hangars safely. Upon his honorable discharge, Raymond returned to the familiar brick grid of Holyoke, where he built a devoted family life alongside his wife, Catherine (Reckart) Brodeur. He lived a full post-war civilian life in the valley before passing away on August 3, 2007, at the age of 82. He rests eternally at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch3"}, {"id": "sj_bassett_merlon", "name": "Merlon Bassett", "era": ["World War II", "Korea", "Vietnam"], "branch": "U.S. Air Force", "branchLabel": "Army & Air Force \u00b7 WWII\u2013Vietnam", "lat": 42.2066, "lng": -72.6281, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/bassett_merlon.jpg", "extraPhotos": [], "narrative": "Merlon Bassett (1926\u20132002) lived a remarkable 22-year saga of military service that spanned three of the nation's major modern conflicts. Born in Portland, Maine, he entered the hazardous maritime shipping lanes of the Merchant Marines at the dawn of World War II before enlisting in the U.S. Army, where he saw combat across the African Campaign and the European Theater. Following the war, while stationed in Panama, he met the love of his life, Beatrice Villasis-Teran. The couple married and permanently settled within the working-class neighborhoods of Holyoke in 1950. Merlon answered the call yet again, transitioning to the U.S. Air Force through the Korean and Vietnam eras until 1962, followed by a final tenure with the 104th Tactical Fighter Group of the Massachusetts Air National Guard. In civilian life, Merlon planted deep roots in the local economy, working for years at the Brown Paper Company and later as a 3rd Class Engineer for the Commonwealth of Massachusetts until his retirement in 1988. Known affectionately in his neighborhood for fixing bicycles for his grandchildren and local children, he passed away peacefully at home on December 26, 2002, at the age of 76. He rests eternally at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch3"}, {"id": "sj_rohan_john_f", "name": "John F. Rohan", "era": "World War II", "branch": "U.S. Army", "branchLabel": "Army \u00b7 WWII", "lat": 42.207, "lng": -72.6296, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/rohan_john_f.jpg", "extraPhotos": [], "narrative": "John F. Rohan (1917\u20132014) was a lifelong Holyoker whose multi-generational family ties left an indelible mark on the city's civic memory. Born on March 8, 1917, John was drafted into the United States Army during World War II, serving as a Technician Fifth Grade (Tec 5). His role required a high degree of technical proficiency, ensuring that critical communications, equipment maintenance, or mechanical infrastructure remained operational behind the lines as the Allied forces pushed forward. After the war, John returned straight to the heart of Holyoke. The Rohan name remains highly respected in local memory; members of his immediate family famously operated the Lucy Hickey Flower Shop on Appleton Street and served the city's infrastructure as workers for the Holyoke Gas and Electric Department. John lived a remarkably long post-war life, passing away on June 21, 2014, at the age of 97. He rests eternally at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch3"}, {"id": "sj_wilmot_frederick_b", "name": "Frederick B. Wilmot", "era": "World War I", "branch": "U.S. Army", "branchLabel": "Army \u00b7 WWI", "lat": 42.207, "lng": -72.6291, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/wilmot_frederick_b.jpg", "extraPhotos": [], "narrative": "Frederick B. Wilmot (1895\u20131971) was raised in the industrial rhythm of Holyoke, where his family was deeply rooted. Born on June 1, 1895, Frederick answered the nation's call during the Great War, climbing to the senior rank of Master Sergeant (MSgt) in Battery F of the 20th Field Artillery. His reality on the battlefields of Europe was defined by the deafening roar of heavy artillery batteries, the choking smell of cordite, and the logistics of coordinating massed firepower across devastated landscapes. On September 1, 1922, following his return to civilian life, he married Holyoke native Anna Gloth in New York. His wife would later become famous in genealogical circles for her extreme longevity, living to be a supercentenarian. Frederick spent decades as a proud fixture of the Holyoke community until his passing on September 20, 1971, at the age of 76. He rests eternally at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": ["Silver Star"], "status": "located", "source": "st-jerome-field-batch3"}, {"id": "sj_kerin_michael_f", "name": "Michael F. Kerin", "era": "World War I", "branch": "U.S. Navy", "branchLabel": "Navy \u00b7 WWI", "lat": 42.207, "lng": -72.6286, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/kerin_michael_f.jpg", "extraPhotos": [], "narrative": "Michael F. Kerin (1896\u20131980) was born in Massachusetts on July 18, 1896, to Irish-American parents Michael and Mary (Lynch) Kerin. Growing up in the traditional neighborhoods of Holyoke, he entered the military during World War I, serving his country as a Yeoman (YEO) in the United States Navy. While infantrymen slogged through the mud of the Western Front, Michael's wartime reality was defined by the relentless clerical and administrative machinery of the fleet, tracking naval manifests, correspondence, and personnel files critical to maintaining the rapid mobilization of the Navy. Following the armistice, Michael returned to civilian life in Holyoke, walking its familiar streets for over sixty years as a veteran and active community member. He passed away on February 2, 1980, at the age of 83. He rests eternally at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch3"}, {"id": "sj_oleary_vincent", "name": "Vincent O'Leary", "era": "World War II", "branch": "U.S. Marine Corps", "branchLabel": "Marine Corps \u00b7 WWII", "lat": 42.207, "lng": -72.6281, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/oleary_vincent.jpg", "extraPhotos": [], "narrative": "Vincent O'Leary (June 27, 1917 \u2013 January 26, 2002) served as a Private First Class in the United States Marine Corps during World War II \u2014 the Corps that carried the island-hopping campaign across the Pacific. He came home to Holyoke after the war. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch3"}, {"id": "sj_murray_charles", "name": "Charles Murray", "era": "", "branch": "", "branchLabel": "", "lat": 42.2074, "lng": -72.6296, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/murray_charles.jpg", "extraPhotos": [], "narrative": "Charles Murray (1859\u20131905) rests at St. Jerome Cemetery with his wife, Catherine Winters (1862\u20131929). A United States veteran's star marks his grave. Born in 1859 and dying in 1905, his service would fall in the peacetime years or the era of the Spanish-American War rather than either World War; the branch and conflict are not recorded on the stone and await research. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch3"}, {"id": "sj_smith_dav", "name": "Smith", "era": "", "branch": "", "branchLabel": "", "lat": 42.2074, "lng": -72.6291, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/smith_dav.jpg", "extraPhotos": [], "narrative": "This Smith family monument at St. Jerome Cemetery is marked with the emblem of the Disabled American Veterans, identifying a disabled veteran among those buried here. The stone is badly weathered: the veteran's given name, branch, and war cannot be read with confidence, and the plot also carries family names including a mother and a Margaret Riley. This entry is provisional and unverified \u2014 the veteran has not yet been positively identified, and the record will be updated once research confirms who he was. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch3"}, {"id": "sj_mcnee_john_g", "name": "John G. McNee", "era": "Korea", "branch": "U.S. Army", "branchLabel": "Army \u00b7 Korea", "lat": 42.206, "lng": -72.63, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/mcnee_john_g.jpg", "extraPhotos": [], "narrative": "John G. McNee (1928\u20132014) was born in Holyoke to Thomas and Mary (Moynihan) McNee. Raised in a devout home, he attended Blessed Sacrament School before learning a trade at Holyoke Trade High School. During the Korean War, John served as a Specialist Third Class in the United States Army. While deploying to England, his technical proficiency was matched by his lethality on the firing line, earning a reputation as an exceptional sharpshooter who was famously noted for the ability to hit a dime from two hundred yards away. Returning home to Holyoke after his service, John transitioned his precise military skills directly into \u201cThe Paper City\u2019s\u201d manufacturing backbone, working for decades as a precision tool maker first for the F.W. Sickles Company and later at Savage Arms, from which he retired in 1993. A passionate lifelong local sportsman, he was deeply involved with the Quabbin Fisherman\u2019s Association, the Western Mass. Fly Tyers Association, and the Western Mass. Duck Hunters. After spending the vast majority of his life in Holyoke, John passed away at home in 2014 at the age of 86. He rests eternally at St. Jerome Cemetery beside his beloved wife, Pauline. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch4"}, {"id": "sj_kane_joseph_d", "name": "Joseph D. Kane", "era": "Korea", "branch": "U.S. Army", "branchLabel": "Army \u00b7 Korea", "lat": 42.206, "lng": -72.6295, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/kane_joseph_d.jpg", "extraPhotos": [], "narrative": "Joseph D. Kane (1924\u20132010) was a true fixture of Holyoke history, remembered affectionately as the very last of the \u201cOld\u201d Ward Four Boys. Born in the city in 1924, Joe grew up running the streets of downtown Holyoke before answering the call of his country during the height of the Korean War. Serving as a Private First Class in the United States Army, his assignment put him on the thin line of authority, serving directly within a Military Police (MP) unit. Upon returning safely to the brick landscape of his youth, Joe married the love of his life, Susan Martunes, on December 26, 1951, at a winter ceremony in the city. He immediately turned his military police experience into a lifelong commitment to his neighbors, joining the Holyoke Police Department. For three decades, Officer Kane walked the beats and patrolled the neighborhoods of Holyoke until his retirement in the early 1980s. Following his wife\u2019s passing in 1991, Joe spent his remaining decades missing her dearly until he passed away on May 29, 2010, at the age of 86. Following a Mass of Christian Burial at Blessed Sacrament Church, he was laid to rest at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch4"}, {"id": "sj_enright_william_f", "name": "William F. Enright", "era": "World War II", "branch": "U.S. Navy", "branchLabel": "Navy \u00b7 WWII", "lat": 42.206, "lng": -72.629, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/enright_william_f.jpg", "extraPhotos": [], "narrative": "William F. Enright (1920\u20131979) served as a Lieutenant, Junior Grade, in the United States Navy during World War II. As a commissioned officer navigating the hazardous oceanic expanses of the global conflict, he bore real responsibility for ship and crew. Right in the middle of the war's mobilization, William returned briefly to the Pioneer Valley to marry Margaret \u201cPeg\u201d Redding\u2014a daughter of Irish immigrants raised right in Holyoke\u2014on September 11, 1943. Once victory was achieved and the uniform came off, William returned to Holyoke to dedicate his entire career to shaping the minds of the city's youth, serving for decades as a longtime principal in the Holyoke Public Schools. He was a familiar and respected figure to generations of local families before his untimely passing in 1979 at the age of 59. He rests eternally at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch4"}, {"id": "sj_duquette_normand", "name": "Normand Duquette", "era": "Vietnam", "branch": "U.S. Air Force", "branchLabel": "Air Force \u00b7 Vietnam", "lat": 42.2058, "lng": -72.6302, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/duquette_normand.jpg", "extraPhotos": [], "narrative": "Normand Duquette (1930\u20131985) made a career of the United States Air Force, rising to the rank of Master Sergeant and serving during the height of the Vietnam War era. His career took him far from the Pioneer Valley, including an overseas deployment stationed in Scotland where he met his beloved wife, Patricia Cameron. Together, they returned to the United States in 1955 to build their family life. As a senior non-commissioned officer, Normand was the vital backbone of the flight line, bearing responsibility for ground operations, technical crews, and combat aircraft readiness. Master Sergeant is a rank achieved through decades of exceptional technical competence and proven leadership. Upon retiring from active duty, Normand returned to the local area, spending his final years tied to the community before his passing on March 25, 1985, at the age of 54. He rests eternally at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch5"}, {"id": "sj_boudreau_james_f", "name": "James F. Boudreau", "era": "Cold War", "branch": "U.S. Navy", "branchLabel": "Navy \u00b7 Cold War", "lat": 42.2058, "lng": -72.6297, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/boudreau_james_f.jpg", "extraPhotos": [], "narrative": "James F. Boudreau (1938\u20131984) served in the United States Navy as a Constructionman. He was part of the Navy\u2019s famed builders\u2014the Seabees\u2014whose legendary creed \u201cWe Build, We Fight\u201d captured a trade requiring sailors to construct critical infrastructure under tactical, high-risk conditions. Born in 1938, James answered the call during the tense undercurrents of the Cold War years. Returning safely to the Pioneer Valley, he married Gail M. O\u2019Connor, a graduate of St. Jerome High School, and together they settled down in Holyoke to raise their four children. He remained deeply connected to local neighborhood institutions and parish life until his untimely passing in 1984 at the early age of 46. He rests eternally at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch5"}, {"id": "sj_cuddy_james_e", "name": "James E. Cuddy", "era": "World War II", "branch": "U.S. Navy", "branchLabel": "Navy \u00b7 WWII", "lat": 42.2058, "lng": -72.6292, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/cuddy_james_e.jpg", "extraPhotos": [], "narrative": "James E. Cuddy (1911\u20131994) served as an Aviation Machinist's Mate Second Class in the United States Navy during World War II. Entering the service at thirty years old, James was older and more experienced than many of the junior sailors around him, providing vital stability to his unit. His rate required mastering the rigorous, grease-and-oil mechanics of naval aviation\u2014tearing down, overhauling, and rebuilding high-performance aircraft engines to ensure pilots could launch from flight decks and safely return home. Surviving the rapid mobilizations of the global war, James returned to civilian life in Holyoke. He lived a remarkably long and full post-war life in the valley before passing away on the final day of the year, December 31, 1994, at the age of 83. He rests eternally at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-field-batch5"}, {"id": "sj_fonseca_joseph_c", "name": "Joseph C. Fonseca", "era": "World War II", "branch": "U.S. Navy", "branchLabel": "Navy \u00b7 WWII", "lat": 42.2052, "lng": -72.6308, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/fonseca_joseph_c.jpg", "extraPhotos": [], "narrative": "Joseph C. Fonseca (1926\u20132003) was part of the broad mobilization of the Pioneer Valley's working-class families during the second global conflict. Born in Springfield on January 9, 1926, to Joaquin and Mary (Costa) Fonseca, he answered the call to arms by enlisting in the United States Navy during World War II. Serving as a Petty Officer Second Class (PO2), Joseph navigated the tense and highly volatile maritime shipping lanes across multiple theaters of war. His honorable combat record is anchored by his decorations, which include the World War II Victory Medal, the American Theatre Medal, and the European-African Theatre Medal. Upon returning home safely, he married his beloved wife of 52 years, Eleanor McGrath\u2014a native Holyoke girl\u2014and settled down across the river to raise their five children. Joseph dedicated over 30 years of his civilian career working as a Food Selector for Sure Fine Foods of Connecticut before his retirement in 1990. A devout family man and a lifelong local veteran, he passed away peacefully on July 16, 2003, at the age of 77. He rests eternally at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-research-batch6"}, {"id": "sj_donoghue_roger_p", "name": "Roger P. Donoghue", "era": "Korea", "branch": "U.S. Army", "branchLabel": "Army \u00b7 Korea", "lat": 42.2052, "lng": -72.63032, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/donoghue_roger_p.jpg", "extraPhotos": [], "narrative": "Roger P. Donoghue (1932\u20132018) was a lifelong Holyoker whose deep roots positioned him as an outstanding and beloved pillar of the local community. Born in the city to Roger and Mary Ellen (O'Connor) Donoghue, he ran the neighborhoods of his youth, graduating from Blessed Sacrament School and the Holyoke High School Class of 1949. He answered his country\u2019s call during the height of the Korean War, serving as a Corporal in the United States Army. His deployment put him face-to-face with the bitter, frozen elements and harsh tactical realities of the Korean theater. Returning safely to the brick streetscapes of Holyoke, Roger pursued higher education at Holyoke Community College and built an exceptionally rich life alongside his wife of over six decades, Marie (Driscoll) Donoghue\u2014proudly cherishing their lifelong Ward 4 roots and St. Jerome parish. He became a widely known and fiercely respected community leader. Roger spent his final days under the care of his community at the Holyoke Soldiers' Home, passing away surrounded by his family on February 2, 2018, at the age of 86. Following a solemn Funeral Mass at the St. Patrick Chapel of St. Jerome Church, he was laid to rest at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-research-batch6"}, {"id": "sj_lajoie_lawrence_v_jr", "name": "Lawrence V. Lajoie Jr.", "era": "World War II", "branch": "U.S. Army", "branchLabel": "Army \u00b7 WWII", "lat": 42.2052, "lng": -72.62984, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/lajoie_lawrence_v_jr.jpg", "extraPhotos": [], "narrative": "Lawrence V. \u201cLarry\u201d Lajoie Jr. (1928\u20132009) belonged to the absolute fabric of the multi-generational, working-class families of Holyoke. Born in the city on February 12, 1928, he stepped out of civilian life during World War II to shoulder the responsibilities of a Corporal in the United States Army. Larry\u2019s wartime experience immersed him in the rigid operational demands and high-stakes discipline of the ground forces during the global liberation campaigns. Upon his honorable discharge, he returned directly to the city he loved. He shared a beautiful, devoted marriage with his wife, Mary (Manuello) Lajoie\u2014a teacher's aide at Holyoke High\u2014and together they became staples of the neighborhood, raising seven children who grew into prominent local community figures. A lifelong communicant of Blessed Sacrament Church, Larry lived out a vibrant post-war life in the valley before passing away on February 5, 2009, at the age of 80. He was laid to rest alongside his wife at St. Jerome Cemetery, remembered always as a good soldier whose legacy endures in a grateful nation. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-research-batch6"}, {"id": "sj_quirk_robert_michael", "name": "Robert Michael Quirk", "era": "Korea", "branch": "U.S. Marine Corps", "branchLabel": "Marine Corps \u00b7 Korea", "lat": 42.2052, "lng": -72.62936, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/quirk_robert_michael.jpg", "extraPhotos": [], "narrative": "Robert Michael Quirk (1933\u20132021) was born in Holyoke on October 13, 1933, growing up amidst the industrial energy of the Pioneer Valley. At the dawn of the 1950s, he stepped forward to answer the nation's call during the Korean War, earning the proud title of a Corporal in the United States Marine Corps. For Robert, carrying the mantle of a Marine meant enduring the punishing, frozen hillsides, treacherous ridge battles, and unrelenting tactical friction that characterized the peninsula's conflict. He survived the war and brought his hard-won military bearing back home to Holyoke, where he spent nearly seventy years contributing to the life and civic memory of his hometown. Robert passed away on January 15, 2021, at the age of 87, leaving behind a proud legacy of service that remains permanently etched on his monument at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-research-batch6"}, {"id": "sj_burns_cornelius_d", "name": "Cornelius D. Burns", "era": "World War II", "branch": "U.S. Army", "branchLabel": "Army \u00b7 WWII", "lat": 42.20558, "lng": -72.6308, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/burns_cornelius_d.jpg", "extraPhotos": [], "narrative": "Cornelius D. Burns (1916\u20132001) was born on May 3, 1916, growing up within the early, robust neighborhoods of Holyoke. He was drafted into the United States Army during World War II, climbing to the rank of Technician Fifth Grade (Tec 5). His vital role required an exceptionally high degree of specialized mechanical and technical competence behind the lines, ensuring that critical supply transport, communications networks, and battalion equipment remained functional as the Allied forces steadily advanced across fractured combat zones. After victory was secured, Cornelius returned to civilian life in Holyoke, walking its familiar canal-lined streetscapes for over fifty years as a proud veteran and a quiet, industrious worker. He passed away on October 7, 2001, at the age of 85, and was laid to rest under a veteran's marker at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-research-batch6"}, {"id": "sj_quinney_edward_j", "name": "Edward J. Quinney", "era": "World War II", "branch": "U.S. Army", "branchLabel": "Army \u00b7 WWII", "lat": 42.20558, "lng": -72.63032, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/quinney_edward_j.jpg", "extraPhotos": [], "narrative": "Edward J. Quinney (1914\u20131992) was born into the working-class rhythm of Holyoke on November 13, 1914. He answered his country\u2019s call during World War II, serving with technical distinction as a Technician Fourth Grade (Tec 4) in the United States Army. As a Sergeant-equivalent technician, Edward\u2019s daily reality under fire was defined by immense mechanical and structural responsibility\u2014repairing essential weaponry, communications gear, or heavy equipment vital to keeping frontline combat elements functioning effectively through grueling theater campaigns. He survived the global conflagration and returned to the valley to build a quiet post-war life within the neighborhood landscape. Edward passed away on September 13, 1992, at the age of 77, leaving behind an unvarnished legacy of duty. He rests eternally at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-research-batch6"}, {"id": "sj_aurnhammer_richard_a", "name": "Richard A. Aurnhammer", "era": "World War II", "branch": "U.S. Army", "branchLabel": "Army \u00b7 WWII", "lat": 42.20558, "lng": -72.62984, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/aurnhammer_richard_a.jpg", "extraPhotos": [], "narrative": "Richard A. Aurnhammer (1924\u20131989) was part of the broad generation of young New England men who threw down their civilian trades to answer the call of duty during World War II. Serving as a Private First Class (PFC) in the United States Army, his war was defined by the raw, day-to-day ground realities of the infantry\u2014shouldering heavy field packs, enduring brutal weather exposures, digging defensive foxholes, and operating under the constant shadow of enemy artillery. He survived the global conflict, honorably returned to civilian status, and lived out his post-war decades as an integrated member of the Holyoke community. Richard passed away in 1989 at the age of 65 and was laid to rest at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-research-batch6"}, {"id": "sj_seklecki_frederick_r", "name": "Frederick R. Seklecki", "era": "Korea", "branch": "U.S. Air Force", "branchLabel": "Air Force \u00b7 Korea", "lat": 42.20558, "lng": -72.62936, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/seklecki_frederick_r.jpg", "extraPhotos": [], "narrative": "Frederick R. Seklecki (1931\u20131992) was raised in the local area and stepped forward to serve his country during the tense years of the Korean War. He enlisted in the United States Air Force, rising to the rank of Airman First Class (A1C). Frederick\u2019s wartime reality centered around the high-tempo maintenance, logistical operations, and flight-line support necessary to keep combat aircraft airborne during the mid-century jet-age conflict. Following his honorable discharge, he returned to the Pioneer Valley to plant his civilian roots, remaining a fixture of local veteran circles until his passing in 1992 at the age of 61. He rests eternally at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-research-batch6"}, {"id": "sj_collins_joseph_f", "name": "Joseph F. Collins", "era": "World War II", "branch": "U.S. Army Air Forces", "branchLabel": "Army Air Forces \u00b7 WWII", "lat": 42.20596, "lng": -72.6308, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/collins_joseph_f.jpg", "extraPhotos": [], "narrative": "Joseph F. Collins (1924\u20132009) was born on May 4, 1924, growing up amidst the industrial backdrop of the local wards. He answered the call of his nation during World War II, enlisting in what was then the United States Army Air Forces. Serving as a Private First Class (PFC), Joseph\u2019s daily reality was tied directly to the soaring mechanics of the air war\u2014operating within ground support divisions, refueling heavy bombers, or managing the vast munitions and logistical bases that fueled the Allied push toward victory. Having honorably survived the conflict, he returned to Holyoke to build a long, stable post-war life. Joseph passed away on August 14, 2009, at the age of 85, and was laid to rest at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-research-batch6"}, {"id": "sj_deane_patrick_f", "name": "Patrick F. Deane", "era": "World War II", "branch": "U.S. Army", "branchLabel": "Army \u00b7 WWII", "lat": 42.20596, "lng": -72.63032, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/deane_patrick_f.jpg", "extraPhotos": [], "narrative": "Patrick F. \u201cShorty\u201d Deane (1912\u20132008) was raised in a traditional Irish-American enclave, attending the former Rosary High School before heading off to study at the College of the Holy Cross in Worcester. Drafted into the United States Army during World War II, Patrick served as a Staff Sergeant within the hard-hitting 14th Armored Division. His wartime reality was defined by the thunderous clank of tanks, heavy logistical movements under enemy fire, and mechanical endurance during the intense Allied drives across Europe. His battlefield valor earned him the Bronze Star Medal. Returning home safely to the Pioneer Valley, Patrick built a long, prosperous civilian life. He spent decades working as a prominent Sales Representative for Liberty Liquors in Springfield until his retirement in 1982. A dedicated civic figure, he was a life member of the Holyoke Lodge of Elks #902 and American Legion Post 325. Following a life spent close to his neighbors and a large family of daughters and grandchildren, Patrick passed away in 2008 at the remarkable age of 96. He rests eternally at St. Jerome Cemetery beside his beloved wife, Rose. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": ["Bronze Star"], "status": "located", "source": "st-jerome-research-batch6"}, {"id": "sj_ducharme_william_m", "name": "William M. Ducharme", "era": "World War II", "branch": "U.S. Army", "branchLabel": "Army \u00b7 WWII", "lat": 42.20596, "lng": -72.62984, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/ducharme_william_m.jpg", "extraPhotos": [], "narrative": "William M. \u201cDuke\u201d Ducharme (1922\u20132005) grew up immersed in the tight-knit musical traditions of the valley. Even before graduating high school, he served as a marching instructor and drum major for the Major J.J. Leonard V.F.W. Post 70 Bugle and Drum Corps. During World War II, William answered the call to arms, serving as a Corporal in the United States Army. His service ground him in the rigid operational discipline of wartime personnel infrastructure. When the uniform came off, William turned his technical experience into a robust career in defense manufacturing, working as a purchasing agent and production controller at the historic Springfield Armory, and later as a foreman in the armament department at General Electric. Yet his true civilian legacy lay in music; he founded the Post 70 Dukes M&M Corps, the Springfield Marksmen Drum and Bugle Corps, and established national scholarships for student musicians. A legendary local drum corps judge and writer, Duke lived a vibrant life before passing away in 2005 at the age of 83. He rests eternally at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-research-batch6"}, {"id": "sj_lynch_walter_a", "name": "Walter A. Lynch", "era": "World War II", "branch": "U.S. Navy", "branchLabel": "Navy \u00b7 WWII", "lat": 42.20596, "lng": -72.62936, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/lynch_walter_a.jpg", "extraPhotos": [], "narrative": "Walter A. Lynch (1895\u20131959) belonged to the multi-generational workforce of Holyoke. Despite being older than the average draft age, he stepped forward to serve his country as an enlisted sailor in the United States Navy during World War II. His daily life at sea was defined by the relentless mechanical hum of the fleet, standing structural watches, and navigating global maritime transport lanes critical to keeping Allied supply lines intact. Returning to civilian life in the Pioneer Valley, Walter settled back into the neighborhood grid, living on Essex Street and dedicating his labor to local civic and industrial sectors. He shared a long, quiet marriage with his wife, Lillian (Mettey) Lynch. Walter passed away in the spring of 1959, leaving a legacy of quiet patriotism. He rests eternally at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-research-batch6"}, {"id": "sj_gately_peter_t", "name": "Peter T. Gately", "era": "World War I", "branch": "U.S. Navy", "branchLabel": "Navy \u00b7 WWI", "lat": 42.20634, "lng": -72.6308, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/gately_peter_t.jpg", "extraPhotos": [], "narrative": "Peter T. Gately (1890\u20131971) was born in Holyoke to Patrick and Margaret (Connors) Gately, growing up within the city\u2019s early industrial wards. He answered the call during the rapid naval mobilization of World War I, serving as a Chief Machinist's Mate (CMM) in the United States Navy. His wartime reality was down in the cavernous, sweltering bellies of naval vessels, commanding black-gang crews to manage heavy steam boilers, complex turbine engines, and mechanical repairs where a single blown valve could cripple a ship at sea. Surviving the dangerous, submarine-threatened waters of the Atlantic, Peter returned home to the brick canals of Holyoke. He spent over fifty years in civilian life as a highly skilled tradesman and a proud member of the local Irish-American community before his passing on December 3, 1971, at the age of 81. He rests eternally at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-research-batch6"}, {"id": "sj_sullivan_james_j", "name": "James J. Sullivan", "era": "Civil War", "branch": "Massachusetts Volunteer Infantry", "branchLabel": "21st Mass. Vol. Inf. \u00b7 Civil War", "lat": 42.20634, "lng": -72.63032, "geo": "provisional", "photo": "/Veteran-Archives/photos/st-jerome/sullivan_james_j.jpg", "extraPhotos": [], "narrative": "James J. Sullivan answered the Union's call in 1861 and served the whole span of the war with Company K, 21st Massachusetts Volunteer Infantry. The 21st was among the hardest-marched regiments of the conflict\u2014it fought at New Bern, stood in the maelstrom of Antietam, faced the stone wall at Fredericksburg, and bled through the Overland Campaign at the Wilderness and Spotsylvania. For a young man from Holyoke, it meant four years of mud, hardtack, and the constant company of death\u2014and he came home from all of it, living until 1911. Back home in the Pioneer Valley, James planted lifelong roots as an industrial laborer, working for decades in the local paper mills that defined the city's growth. He shared his life with his wife, Ellen Kelliher, raising a family that watched the city transform from a rough canal settlement into a manufacturing titan. He rests with his family beneath the striking Sullivan monument at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-research-batch6"}, {"id": "sj_narey_francis_h", "name": "Francis H. Narey", "era": "Korea", "branch": "U.S. Army", "branchLabel": "Army \u00b7 Korea", "lat": 42.205, "lng": -72.6312, "geo": "provisional", "photo": "", "extraPhotos": [], "narrative": "Francis H. Narey served as a Private First Class in the United States Army during the Korean War. Born in 1928, he came of age just in time for the \u201cForgotten War,\u201d shouldering the rifleman's burden of frozen ridgelines, hard winters, and a grinding, stalemated front on the far side of the world. He returned home to the Pioneer Valley and lived a long life, dying in 2013 at the age of 84. He rests at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-research-batch7"}, {"id": "sj_pare_richard_a", "name": "Richard A. Pare", "era": "World War II", "branch": "U.S. Navy", "branchLabel": "Navy \u00b7 WWII", "lat": 42.205, "lng": -72.6307, "geo": "provisional", "photo": "", "extraPhotos": [], "narrative": "Richard A. Pare served in the United States Navy during World War II. Born in 1922, he answered the call as the nation mobilized for a two-ocean war, taking his place among the sailors who kept the fleet and its supply lines moving through contested waters. He came home to the valley and lived a long life, dying in 2010 at the age of 87. He rests at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-research-batch7"}, {"id": "sj_lynch_daniel_e", "name": "Daniel E. Lynch", "era": "World War II", "branch": "U.S. Navy", "branchLabel": "Navy \u00b7 WWII", "lat": 42.205, "lng": -72.6302, "geo": "provisional", "photo": "", "extraPhotos": [], "narrative": "Daniel E. Lynch served as an Ensign in the United States Navy during World War II \u2014 a commissioned officer's first rank, standing watches and leading enlisted sailors aboard a fleet fighting across two oceans. Born in 1925, he came home after the war to a long civilian life, dying in 1996 at the age of 70. He rests at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-research-batch7"}, {"id": "sj_sullivan_paul_e", "name": "Paul E. Sullivan", "era": "World War II", "branch": "U.S. Marine Corps", "branchLabel": "Marine Corps \u00b7 WWII", "lat": 42.2054, "lng": -72.6312, "geo": "provisional", "photo": "", "extraPhotos": [], "narrative": "Paul E. Sullivan served in the United States Marine Corps during World War II \u2014 the Corps that carried the island-hopping campaign across the Pacific, from the beaches to the jungle ridgelines. Born on the last day of 1917, he answered the call in the war's great mobilization and returned home to the valley. He rests at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-research-batch7"}, {"id": "sj_smith_william_d", "name": "William D. Smith", "era": "Cold War", "branch": "U.S. Marine Corps", "branchLabel": "Marine Corps \u00b7 Cold War", "lat": 42.2054, "lng": -72.6307, "geo": "provisional", "photo": "", "extraPhotos": [], "narrative": "William D. Smith served as a Lance Corporal in the United States Marine Corps. Born in 1940, he wore the eagle, globe, and anchor in the Cold War years \u2014 his marker records no specific war \u2014 carrying the discipline that title has always demanded. He rests at St. Jerome Cemetery. If you have further information about this veteran, please contact the City of Holyoke Veterans Graves Officer at (413) 322-5630 at 310 Appleton Street, 1st Floor, Holyoke, MA 01040.", "badges": [], "status": "located", "source": "st-jerome-research-batch7"}]};
